const $=s=>document.querySelector(s), icon=n=>`<img class="ico" src="assets/${n}.svg" alt="">`, esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routeNames={journey:'Journey & screens',welcome:'First scan',overview:'Overview',scan:'New scan',progress:'Scan progress',result:'Release evidence',rebuild:'Verify a fix',verified:'Rebuilt evidence',releases:'Releases',sources:'Coverage',alerts:'Alerts',timeline:'Timeline',notifications:'Notifications',policy:'Policy & allowlist',team:'Team & roles',workspaces:'Workspaces',billing:'Plan & billing',retention:'Retention',audit:'Audit log',health:'Install health',tokens:'Scan API tokens',registries:'Private registries',concepts:'Visual concepts'};
const routeIcons={journey:'BookOpen',welcome:'Zap',overview:'Gauge',scan:'Package',progress:'Clock3',result:'FileCheck2',rebuild:'RefreshCw',verified:'ShieldCheck',releases:'FileCheck2',sources:'Boxes',alerts:'Bell',timeline:'Activity',notifications:'Bell',policy:'SlidersHorizontal',team:'Users',workspaces:'Boxes',billing:'CreditCard',retention:'Clock3',audit:'History',health:'Activity',tokens:'KeyRound',registries:'LockKeyhole',concepts:'BookOpen'};
let route='overview',sub='',mode='normal',sampleFile=true,scanOrigin='upload',reviewed=false,rebuilt=false,alertState='open',savedPolicy=false,notificationSent=false,workspaceName='Studio workspace',toastTimer;
const b=(text,to,primary=false,ic='ArrowRight')=>`<a class="button ${primary?'primary':''}" href="#${to}">${text}${ic?icon(ic):''}</a>`;
const btn=(text,action,primary=false,ic='')=>`<button class="button ${primary?'primary':''}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const status=(text,kind='neutral')=>`<span class="status ${kind}">${text}</span>`;
const head=(title,description,action='')=>`<div class="page-head"><div><div class="eyebrow">${esc(workspaceName)}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
const tabs=(items,selected)=>`<nav class="tabs" aria-label="${routeNames[route]} sections">${items.map(([id,title])=>`<a href="#${route}/${id}" class="${id===selected?'selected':''}" ${id===selected?'aria-current="page"':''}>${title}</a>`).join('')}</nav>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const entity=(title,caption,ic='Package',to='result')=>`<a class="entity" href="#${to}"><span class="icon-box">${icon(ic)}</span><span><strong>${title}</strong><small>${caption}</small></span></a>`;
const empty=(title,description,action,ic='Package')=>`<div class="empty">${icon(ic)}<h2>${title}</h2><p>${description}</p>${action}</div>`;
const field=(label,input,help='')=>`<label class="field">${label}${input}${help?`<small>${help}</small>`:''}</label>`;
const notice=(title,text,kind='neutral')=>`<div class="notice">${icon(kind==='passed'?'ShieldCheck':'CircleAlert')}<div><strong class="${kind}">${title}</strong><p>${text}</p></div></div>`;
const section=(title,body,action='')=>`<section class="section"><div class="section-head"><h2>${title}</h2>${action}</div>${body}</section>`;
const setting=(title,description,control)=>`<div class="setting-row"><div><h3>${title}</h3><p>${description}</p></div>${control}</div>`;
const toggle=(label,checked=true)=>`<input class="toggle" type="checkbox" aria-label="${label}" ${checked?'checked':''}>`;
const pick=(label,values)=>`<select aria-label="${label}" class="filter">${values.map(x=>`<option>${x}</option>`).join('')}</select>`;
function drawShell(){const active=['result','rebuild','verified'].includes(route)?'releases':route;$('#sidebar').innerHTML=`<div class="brand"><a href="#overview" aria-label="NoSpoilers overview"><img class="wordmark" src="assets/wordmark.png" alt="NoSpoilers"><img class="mark" src="assets/mark.png" alt="NoSpoilers"></a><button class="collapse" data-action="collapse" aria-label="Toggle sidebar">${icon('PanelLeftClose')}</button></div><button class="workspace" data-action="workspace"><span class="avatar">ST</span><span>${esc(workspaceName)}</span>${icon('ChevronDown')}</button><nav aria-label="Main navigation">${['overview','alerts','sources','releases','timeline'].map(n=>`<a href="#${n}" class="${active===n?'active':''}" title="${routeNames[n]}">${icon(routeIcons[n])}<span>${routeNames[n]}</span>${n==='alerts'?'<span class="nav-count">2</span>':''}</a>`).join('')}<div class="nav-group">WORKSPACE</div>${['notifications','policy','team','workspaces'].map(n=>`<a href="#${n}" class="${active===n?'active':''}" title="${routeNames[n]}">${icon(routeIcons[n])}<span>${routeNames[n]}</span></a>`).join('')}<div class="nav-group">ADMINISTRATION</div>${['retention','audit','health','tokens','registries'].map(n=>`<a href="#${n}" class="${active===n?'active':''}" title="${routeNames[n]}">${icon(routeIcons[n])}<span>${routeNames[n]}</span></a>`).join('')}</nav><div class="sidebar-foot"><span class="avatar">ST</span><span>Studio Team<small>Workspace admin</small></span><a href="#billing" aria-label="Plan and billing">${icon('Settings2')}</a></div>`;$('#topbar').innerHTML=`<button class="mobile-menu" data-action="menu" aria-label="Open navigation">${icon('PanelLeftOpen')}</button><span class="crumb">${icon(routeIcons[route])}${routeNames[route]}</span><a class="trial" href="#billing">Trial · 4 days left</a><span class="top-spacer"></span><button class="search-trigger" data-action="search" aria-label="Search screens and releases">${icon('Search')}<span>Search releases, sources…</span><kbd>⌘ K</kbd></button><span class="topbar-scan">${b('New scan','scan',false,'Plus')}</span><a class="avatar" href="#team" aria-label="Team">ST</a>`;}
function statePicker(){return `<div class="state-picker"><span>PREVIEW STATE</span><select class="filter" id="state" aria-label="Preview state"><option value="normal" ${mode==='normal'?'selected':''}>With records</option><option value="empty" ${mode==='empty'?'selected':''}>New workspace</option><option value="error" ${mode==='error'?'selected':''}>Could not load</option><option value="readonly" ${mode==='readonly'?'selected':''}>Viewer access</option><option value="ended" ${mode==='ended'?'selected':''}>Coverage ended</option></select></div>`;}
const releaseRows=()=>[[entity('Web build','v1.8.0 · web-build.zip'),'Today, 10:42',status('Needs review','review'),'64',b('Open','result',false,'ChevronRight')],[entity('API package','v2.4.1 · api-package.tgz'),'14 Sep, 15:17',status('Policy passed','passed'),'218',btn('Open','api-evidence',false,'ChevronRight')],[entity('Web build','v1.7.9 · web-build.zip'),'11 Sep, 09:03',status('Policy passed','passed'),'52',btn('Open','older-evidence',false,'ChevronRight')]];
function overview(){if(mode==='empty')return head('Your first release starts here.','Get useful evidence from the exact build you plan to ship.')+empty('Check a build in minutes','Upload a release archive, or connect a repository with a published release.',b('Run your first scan','scan',true),'Package');return head('Your releases, at a glance.','One build needs a closer look.',b('New scan','scan',true,'Plus'))+`<section class="hero"><div class="hero-top"><span class="eyebrow">Latest release</span>${status('Needs review','review')}</div><h2>Web build <span class="muted">· v1.8.0</span></h2><p>An embedded source map includes original source code.</p>${b('Review finding','result',true,'ArrowUpRight')}<div class="hero-foot"><span>64 files inspected</span><span>16 Sep 2026, 10:42</span><span>Production not checked</span></div></section><div class="stat-strip"><a class="stat" href="#releases"><strong>6</strong><span>Saved scans</span></a><a class="stat" href="#result"><strong class="review">1</strong><span>Needs review</span></a><a class="stat" href="#sources"><strong>3</strong><span>Connected sources</span></a></div>`+section('Recent release scans',table(['Build','Scanned','Result','Files',''],releaseRows()),`<a class="link" href="#releases">All releases ${icon('ArrowRight')}</a>`)+section('Source activity',`<div class="activity-row"><span></span><div class="ticks-labels">${['Thu 10','Fri 11','Sat 12','Sun 13','Mon 14','Tue 15','Wed 16'].map(d=>`<span>${d}</span>`).join('')}</div><small>Last 7 days</small></div>${['GitHub releases','Uploaded builds','Production websites'].map((x,i)=>`<div class="activity-row"><span>${x}</span><div class="ticks" aria-label="${i===2?'No website configured':'Illustrative recorded check activity'}">${Array.from({length:42},(_,j)=>`<i class="${i===2?'':j%8===i?'green':j===31&&i===1?'amber':''}"></i>`).join('')}</div><small>${i===2?'Not configured':'Recorded checks'}</small></div>`).join('')}<p class="micro">Recorded checks, not a continuous uptime or safety measure.</p>`,`<a class="link" href="#timeline">View timeline ${icon('ArrowRight')}</a>`);}
function welcome(){return head('Start with what you ship.','You don’t need to configure everything to get your first result.')+`<div class="split"><div><section class="hero"><div class="eyebrow">Your first scan</div><h2>Have a release archive?</h2><p>Upload the package or build your customers receive. We’ll inspect it and save the findings in this workspace.</p>${b('Upload a build','scan',true,'Upload')}<p class="micro">No repository connection required.</p></section>${section('Or connect a release source',setting('GitHub release','Choose a repository with a published release attachment.',b('Connect GitHub','scan/github',false,'Github'))+setting('Production website','Verify ownership before checking public assets.',b('Add website','scan/website',false,'Globe')))}</div><aside class="side-note"><div class="note-block"><h3>Three steps to useful evidence</h3><ol class="step-list"><li><span class="step-num">1</span><div><strong>Choose your artifact</strong><p>A release archive, package or website.</p></div></li><li><span class="step-num">2</span><div><strong>Review the result</strong><p>See exactly what was checked.</p></div></li><li><span class="step-num">3</span><div><strong>Act on a finding</strong><p>Fix, rebuild and verify the change.</p></div></li></ol></div></aside></div>`;}
function scan(){const selected=sub||'upload';let form='';if(selected==='upload')form=`<div class="dropzone">${icon('Package')}<h2>Drop your release archive here</h2><p>.zip, .tgz, .tar and supported packages · up to 80 MiB</p>${btn('Choose sample build','sample-file',false,'Upload')}</div>${sampleFile?`<div class="selected-file">${icon('File')}<div><strong>web-build-v1.8.0.zip</strong><small>4.2 MB · ready to scan</small></div><button data-action="remove-file" aria-label="Remove selected build">${icon('X')}</button></div>`:''}${field('Save in',pick('Save in',[workspaceName]))}<button class="button primary" data-action="scan" ${!sampleFile||mode==='ended'||mode==='readonly'?'disabled':''}>Scan this build ${icon('ArrowRight')}</button><p class="micro">Artifacts are inspected, never executed.</p>`;else if(selected==='github')form=`<h2>Check a published release.</h2><p class="micro">Choose from the repositories this workspace can access.</p>${field('Repository',pick('Repository',['studio/web-app']))}${notice('Release available','v1.8.0 · web-build.zip · published 16 Sep 2026','passed')}${btn('Scan latest release','scan',true)}<div class="setting-row"><div><h3>Another GitHub account?</h3><p>Connect a new installation without moving existing evidence.</p></div>${btn('Connect GitHub','connect')}</div>`;else if(selected==='website')form=`<h2>Check your deployed website.</h2>${field('Website URL','<input type="url" value="https://app.example.com" aria-label="Website URL">')}${notice('Ownership verification required','Add the verification file or DNS record before scans can run.')}<div class="path"><code>https://app.example.com/.well-known/nospoilers.txt</code></div>${btn('Preview ownership verification','ownership',true)}<p class="micro">Only supported public assets on the verified origin are checked.</p>`;else form=`<h2>Verify an existing proof.</h2><p class="micro">Check a saved receipt’s signature. This does not rescan the artifact.</p><div class="dropzone">${icon('ShieldCheck')}<h2>Choose a release proof JSON</h2><p>No artifact upload or active scanning plan required.</p>${btn('Use sample proof','proof',true)}</div>`;return head('Check what you’re about to ship.','Choose the exact artifact your customers will receive.')+tabs([['upload',`${icon('Upload')} Upload a build`],['github',`${icon('Github')} GitHub release`],['website',`${icon('Globe')} Website`],['proof',`${icon('ShieldCheck')} Verify proof`]],selected)+`<div class="split"><section>${form}</section><aside class="side-note"><div class="note-block"><h3>What this checks</h3>${['Source maps and source files','Credentials and sensitive files','Your workspace scan policy'].map(x=>`<p>${icon('Check')} ${x}</p>`).join('')}</div><div class="note-block"><h3>What this doesn’t prove</h3><p>A clean artifact scan does not verify your deployed website or guarantee the absence of every vulnerability.</p><a class="link" href="#policy">Review scan rules ${icon('ArrowRight')}</a></div></aside></div>`;}
function progress(){return head('Your build is being checked.','web-build-v1.8.0.zip · Studio workspace')+`<div class="split"><section><div class="quiet-panel"><div class="hero-top"><h2>Inspecting the artifact</h2>${status('Scanning','neutral')}</div><div class="progress-track"><span></span></div><p>Checking file contents against your workspace policy.</p></div><ol class="step-list"><li><span class="step-num">${icon('Check')}</span><div><strong>Artifact received</strong><p>4.2 MB · archive accepted</p></div></li><li><span class="step-num">2</span><div><strong>Inspect files</strong><p>A result is not available until inspection finishes.</p></div></li><li><span class="step-num">3</span><div><strong>Save signed evidence</strong><p>Open the result when it is ready.</p></div></li></ol>${b('Preview completed result','result',true)}<p class="micro">Prototype progression is manual. No real scan is running.</p></section><aside class="side-note"><h3>You can leave this page</h3><p>The real scan continues in the background. Find it later in Releases → Attempts.</p>${b('View attempts','releases/attempts')}</aside></div>`;}
function result(clean=false){const selected=sub||'findings';return head(clean?'Web build · v1.8.1':'Web build · v1.8.0',clean?'The rebuilt artifact passed the selected scan policy.':`web-build-v1.8.0.zip · ${scanOrigin==='github'?'GitHub release':'Uploaded artifact'}`,clean?b('View releases','releases',false,'ArrowRight'):b('Verify a fix','rebuild',true,'ArrowRight'))+status(clean?'Policy passed':'Needs review',clean?'passed':'review')+`<div class="metadata"><span>${icon('File')} ${clean?'63':'64'} files inspected</span><span>${icon('CircleAlert')} ${clean?'0 findings':'1 finding'}</span><span>${icon('Clock3')} 16 Sep 2026, ${clean?'11:08':'10:42'}</span><span>${icon('Globe')} Production not checked</span></div>`+tabs([['findings',clean?'Findings 0':'Findings 1'],['files','Files'],['history','History'],['proof','Proof']],selected)+(selected==='files'?table(['File','Type','Size'],[['dist/assets/app.js','JavaScript','184 KB'],...(!clean?[['dist/assets/app.js.map','Source map','312 KB']]:[]),['dist/index.html','HTML','4 KB']])+`<p class="micro">Sample manifest excerpt · ${clean?'63':'64'} total files in the illustrative scan.</p>`:selected==='history'?feed([...(rebuilt?[['11:08','Rebuilt artifact checked','Original finding absent in v1.8.1','verified']]:[]),...(reviewed?[['10:56','Reviewed change recorded','Human-declared link to the fix','rebuild']]:[]),['10:42','Original scan completed','One source map finding saved','result']]):selected==='proof'?`<div class="split"><div><h2>Signed scan evidence</h2><p class="micro">The proof binds this result to the scanned artifact’s digest.</p>${table(['Property','Value'],[['Artifact',clean?'web-build-v1.8.1.zip':'web-build-v1.8.0.zip'],['Proof signature',status('Valid in sample','passed')],['Scope','Artifact bytes · point-in-time scan'],['Production','Not verified']])}${btn('Preview proof verification','proof',true)}</div><aside class="side-note"><h3>Proof has a scope</h3><p>A valid signature shows that the record has not changed. It does not establish that a deployed website matches this artifact.</p></aside></div>`:clean?`${notice('The original finding is absent in this rebuild','The original scan remains unchanged. This comparison applies to the selected artifact and finding.','passed')}<div class="two-col"><section class="quiet-panel"><div class="eyebrow">Original · v1.8.0</div><h2>Source code embedded in map</h2><p>dist/assets/app.js.map</p><p>${status('Needs review','review')}</p></section><section class="quiet-panel"><div class="eyebrow">Rebuild · v1.8.1</div><h2>Finding not detected</h2><p>63 files inspected · same scoped rule</p><p>${status('Verified absent','passed')}</p></section></div><div class="finding-bottom">${b('Set up follow-up notifications','notifications',true,'Bell')}<p class="micro">Reviewed change and build linkage are human-declared, not provider-attested.</p></div>`:`<div class="finding-layout"><aside class="finding-list"><h3>Findings <span class="pill">1</span></h3><button class="finding-button" data-action="finding-focus"><strong>Source map contains original code</strong><small>dist/assets/app.js.map</small></button></aside><article class="finding-body"><h2 id="finding-title" tabindex="-1">Original source included in build</h2><p>This map includes readable source code in the release archive.</p><div class="eyebrow section">Affected file</div><div class="path">${icon('File')}<code>dist/assets/app.js.map</code></div><div class="two-col explain"><section><h3>Why it matters</h3><p>Anyone who downloads this build can recover the source embedded in the map, including internal comments and implementation details.</p></section><section><h3>What to change</h3><p>Exclude the map from the public build output. Rebuild, then scan the new archive to check that this finding is gone.</p></section></div><div class="finding-bottom">${b('Verify a rebuilt artifact','rebuild',true)}<p class="micro">Original evidence is preserved. A note alone does not verify a fix.</p></div></article></div>`);}
function rebuild(){return head('Verify the fix.','Keep the original finding and the rebuilt evidence connected.')+`<div class="split"><section>${notice('Source map contains original code','Original: web-build-v1.8.0.zip · dist/assets/app.js.map','review')}<h2>1. Record what changed</h2>${field('Investigation note','<textarea id="review-note" placeholder="What did you find and change?">Removed public source maps from the release archive.</textarea>')}${field('Change or pull request URL','<input id="change-url" type="url" value="https://github.com/example/web-app/pull/42">')}${field('Full reviewed commit hash','<input id="commit" value="e17c4eabe40d9c2918f6c657fc325c21a9b8066d" minlength="40" maxlength="40">')}${field('Human review','<span><input id="review-check" type="checkbox">I reviewed this change and its connection to the rebuild.</span>')}${btn('Record sample review','review-save',true)}<div class="section"><h2>2. Check the rebuilt artifact</h2><p class="micro">Select the rebuilt artifact after recording your review.</p><div class="selected-file">${icon('Package')}<div><strong>web-build-v1.8.1.zip</strong><small>Sample rebuilt artifact · 4.0 MB</small></div></div><button class="button primary" id="rebuild-button" data-action="rebuild" ${reviewed?'':'disabled'}>Check rebuilt artifact ${icon('ArrowRight')}</button></div></section><aside class="side-note"><div class="note-block"><h3>Two different records</h3><p>Your note explains the investigation. The reviewed change identifies what you approved. Neither replaces a scan of the rebuilt bytes.</p></div><div class="note-block"><h3>Keep the audit trail</h3><p>The original finding is never rewritten. A new observation records whether it is present in the selected rebuild.</p></div></aside></div>`;}
function releases(){const selected=sub||'uploads';return head('Release evidence.','Find a build, understand its result, or return to an unfinished attempt.',b('New scan','scan',true,'Plus'))+tabs([['uploads','Uploaded builds'],['connected','Connected releases'],['attempts','Attempts']],selected)+`<div class="toolbar"><input type="search" class="filter" id="release-search" placeholder="Find a build…" aria-label="Find a build">${pick('Result filter',['All results','Needs review','Policy passed'])}</div>`+(mode==='empty'?empty('No saved releases yet','Run a scan to save your first artifact result.',b('Scan a build','scan',true)):selected==='attempts'?table(['Attempt','Source','Status',''],[[entity('Web build','Started today, 10:42'),'Upload',status('Completed','passed'),b('View result','result')],[entity('Earlier archive','15 Sep, 16:21'),'Upload',status('Unsupported archive','warn'),b('Try another build','scan')]]):selected==='connected'?table(['Release','Source','Result',''],[[entity('API package','v2.4.1','Github','verified'),'GitHub release',status('Policy passed','passed'),btn('View evidence','api-evidence')]]):`<div id="release-table">${table(['Build','Scanned','Result','Files',''],releaseRows())}</div><p class="micro">A passed policy applies to the scanned artifact. Production checks are separate.</p>`);}
function sources(){const selected=sub||'all';return head('Know what’s being checked.','Connection, monitoring and latest result are separate states.',btn('Connect source','connect',true,'Plus'))+tabs([['all','All sources 3'],['github','GitHub 1'],['packages','Packages 1'],['websites','Websites 1']],selected)+(mode==='empty'?empty('Connect your first source','Connect GitHub or add a website to keep release checks in one place.',btn('Connect source','connect',true)):table(['Source','Connection','Latest check',''],(selected==='all'||selected==='github'?[[entity('studio/web-app','GitHub · release assets','Github','scan/github'),status('Connected','passed'),status('Needs review','review'),b('View release','result')]]:[]).concat(selected==='all'||selected==='packages'?[[entity('@studio/api','Package registry','Package','releases/connected'),status('Connected','passed'),status('Policy passed','passed'),b('View release','verified')]]:[],selected==='all'||selected==='websites'?[[entity('app.example.com','Production website','Globe','scan/website'),status('Verify ownership','warn'),'Not scanned',b('Verify domain','scan/website')]]:[])))+section('Connection health',`<div class="notice">${icon('Activity')}<div><strong>One website needs verification</strong><p>Repository access alone does not establish ownership of a production domain.</p></div><a class="link" href="#health">Review ${icon('ArrowRight')}</a></div>`);}
function alerts(){const selected=sub||'open';return head('Alerts.','Review findings and incomplete checks without mixing them together.')+tabs([['open','Open 2'],['progress','In progress'],['resolved','Resolved']],selected)+(selected==='resolved'||mode==='empty'?empty('No resolved alerts','Alerts appear here after a response is recorded.',b('Back to open alerts','alerts/open'), 'CheckCheck'):selected==='progress'&&alertState!=='progress'?empty('Nothing in progress','Acknowledge an open alert when you start investigating.',b('Review open alerts','alerts/open'),'Clock3'):`<div class="inbox"><aside class="inbox-list"><button class="inbox-row selected" data-action="alert-finding"><strong>Web build · v1.8.0</strong><small class="review">Source code included in map</small></button><button class="inbox-row" data-action="alert-incomplete"><strong>studio/marketing-site</strong><small>Published release missing</small></button></aside><article class="inbox-body" id="alert-body">${alertDetail(false)}</article></div>`);}
function alertDetail(incomplete){return `<div class="actions">${btn(alertState==='progress'?'In progress':'Acknowledge','acknowledge',true)}${btn('Assign','assign')}</div><div class="section">${status(incomplete?'Check incomplete':'Finding needs review',incomplete?'warn':'review')}<h2>${incomplete?'No published release to inspect.':'Source code included in map.'}</h2><p>${incomplete?'This repository has no supported release attachment. That is not evidence of a leak.':'The uploaded web build contains a source map with embedded source code.'}</p></div><section class="explain section"><h3>Next step</h3><p>${incomplete?'Publish an eligible release attachment, or upload the packed build directly.':'Review the affected file, remove it from public output and check a rebuilt artifact.'}</p><div class="section">${b(incomplete?'Upload a build':'Review evidence',incomplete?'scan':'result',true)}</div></section><p class="micro">Acknowledging or resolving an alert changes your response status, not the scan result.</p>`;}
function feed(rows){return `<div class="feed">${rows.map(([time,title,copy,to])=>`<div class="feed-row"><time>${time}</time>${icon(title.includes('review')?'CheckCheck':'FileCheck2')}<div><strong>${title}</strong><p>${copy}</p></div><a class="link" href="#${to}">View ${icon('ArrowUpRight')}</a></div>`).join('')}</div>`;}
function timeline(){return head('The story behind each release.','Recorded scans, responses and delivery events in one place.')+tabs([['all','All activity'],['scans','Scans'],['responses','Responses'],['deliveries','Deliveries']],sub||'all')+`<div class="section-head"><h2>Today · 16 September</h2>${pick('Activity period',['Last 7 days','Last 30 days'])}</div>`+(sub==='deliveries'?empty('No delivery recorded','A saved notification destination does not prove a message arrived.',b('Review notifications','notifications'),'Bell'):feed(sub==='responses'?(reviewed?[['10:56','Reviewed change recorded','Studio admin linked a reviewed fix to the original finding.','rebuild']]:[]):[...(rebuilt?[['11:08','Rebuilt artifact checked','Web build v1.8.1 · original finding absent','verified']]:[]),...(reviewed&&sub!=='scans'?[['10:56','Reviewed change recorded','Studio admin linked a reviewed fix to the original finding.','rebuild']]:[]),['10:42','Scan completed with a finding','Web build v1.8.0 · source map includes original code','result'],['10:41','Artifact submitted','web-build-v1.8.0.zip · 4.2 MB','releases/attempts']]))+`<p class="micro">Sample history. Missing events are not evidence that nothing happened.</p>`;}
function notifications(){const selected=sub||'destinations';return head('Keep the right people informed.','Choose a destination, then check delivery—not just configuration.',selected==='destinations'?btn('Add destination','destination',true,'Plus'):'')+tabs([['destinations','Destinations'],['routing','Routing'],['history','Delivery history']],selected)+(selected==='routing'?`${setting('Release findings','Notify on completed scans with findings.',toggle('Release findings'))}${setting('Incomplete checks','Notify when a source could not be inspected.',toggle('Incomplete checks'))}${setting('Destination','Send enabled events to your selected destination.',pick('Routing destination',['Release webhook']))}<div class="savebar"><span>Changes apply only to future events.</span>${btn('Save sample routing','save',true)}</div>`:selected==='history'?table(['Event','Destination','Delivery',''],[[entity('Test notification','16 Sep, 11:20','Bell','notifications'),'Release webhook',status(notificationSent?'Delivered in preview':'Not sent',notificationSent?'passed':'neutral'),btn('Preview test delivery','notification-test')]]):`${table(['Destination','Type','Status',''],[[entity('Release webhook','hooks.example.com · redacted endpoint','Bell','notifications'),'Webhook',status(notificationSent?'Test delivered':'Not tested',notificationSent?'passed':'warn'),btn('Preview test','notification-test')]])}${section('Available channels',setting('Email','Provider is not configured in this design scenario.',status('Unavailable','neutral'))+setting('Delivery history','Check the recorded outcome of each message.',b('Open history','notifications/history')))}<p class="micro">Prototype tests simulate delivery locally. No message is sent.</p>`);}
function policy(){const selected=sub||'rules';return head('Define what needs review.','Rules apply to scans in this workspace. Changes are explicit and auditable.')+tabs([['rules','Scan rules'],['exceptions','Exceptions'],['signing','Signing'],['allowlist','GitHub allowlist']],selected)+(selected==='rules'?`<div class="split"><section>${setting('Embedded source code','Flag source maps that include original source content.',toggle('Embedded source code'))}${setting('Credentials and sensitive files','Flag supported credential patterns and private files.',toggle('Credentials and sensitive files'))}${setting('Development artifacts','Review internal documentation and development-only output.',toggle('Development artifacts'))}${setting('Review threshold','Select the severity that requires attention.',pick('Review threshold',['Warnings and above','Critical only']))}<div class="savebar"><span>${savedPolicy?'Sample changes saved.':'Current rules remain effective until saved.'}</span>${btn('Save sample rules','policy-save',true)}</div></section><aside class="side-note"><h3>A policy result has limits</h3><p>Passing these rules is not a guarantee that every possible leak or vulnerability has been detected.</p><a href="#audit" class="link">View change history ${icon('ArrowRight')}</a></aside></div>`:selected==='exceptions'?empty('No active exceptions','Exceptions should identify a specific rule and scope, with a reason and expiry.',btn('Propose exception','exception',true),'ShieldCheck'):selected==='signing'?`${notice('Document checks, not cryptographic verification','A required signing document can be checked for presence. That does not validate its signature.')}<div>${setting('Require signing documentation','Check for the expected document in eligible artifacts.',toggle('Require signing documentation',false))}</div>`:`${setting('Approved GitHub owners','Connections still require explicit workspace authority.',field('GitHub owner','<input value="studio" aria-label="GitHub owner">'))}<div class="savebar"><span>Allowlist changes do not grant access.</span>${btn('Save sample allowlist','save',true)}</div>`);}
function team(){return head('The right access for each person.','Invite named people to this workspace with an explicit role.',btn('Invite person','invite',true,'Plus'))+tabs([['members','Members 2'],['invitations','Invitations']],sub||'members')+(sub==='invitations'?empty('No pending invitations','An invitation stays pending until the named person accepts.',btn('Invite person','invite',true),'Users'):table(['Person','Role','Access',''],[[entity('Studio owner','owner@example.com','Users','team'),'Owner',status('Active','passed'),''],[entity('Alex Morgan','alex@example.com','Users','team'),'Viewer',status('Active','passed'),btn('Edit role','role')]]))+`<p class="micro">Membership is workspace-specific. There is no automatic email-domain or agency-wide access.</p>`;}
function workspaces(){return head('A home for every release.','Keep sources, people and evidence in the right workspace.')+tabs([['list','Workspaces'],['connections','Connections'],['organisation','Organisation']],sub||'list')+(sub==='organisation'?`${setting('Studio organisation','Manage shared organisation details and plan.',b('Plan & billing','billing'))}${setting('People and invitations','Explicit workspace access for each person.',b('Team & roles','team'))}${setting('Administrative history','Review changes to this workspace.',b('Audit log','audit'))}`:sub==='connections'?table(['Connection','Workspace','Status'],[[entity('studio','GitHub installation','Github','sources'),workspaceName,status('Connected','passed')]]):table(['Workspace','Your role','Sources',''],[[entity(workspaceName,'Personal workspace','Boxes','overview'),'Admin','3',b('Open','overview')]]))+`<p class="micro">Create another workspace from the workspace switcher in the sidebar.</p>`;}
function billing(){return head('Your plan, clearly.','Coverage and billing status for the selected organisation.')+`<section class="quiet-panel"><div class="hero-top"><div><div class="eyebrow">Current coverage</div><h2>Five-day trial</h2><p>Ends 20 September 2026 · 4 days remaining</p></div>${status('Active','passed')}</div></section>${notice('Checkout is unavailable in this preview','No payment provider is connected. Plan buttons below show design only.')}<div class="plan-grid">${[['Solo','29','For an individual release workflow.'],['Team','99','For a shared workspace and team workflow.']].map(([n,p,d])=>`<section class="quiet-panel"><h2>${n}</h2><div class="price">$${p}<small> USD / month</small></div><p>${d}</p><div class="section"><button class="button" disabled>Checkout unavailable</button></div></section>`).join('')}</div><p class="micro">Both plans use the shared five-day trial. This prototype does not renew trials or change a subscription.</p>`;}
function retention(){return head('Keep evidence deliberately.','Understand what stays available and what expires.')+`<div class="split"><section>${setting('Evidence retention','Applied to eligible records according to the workspace retention policy.',pick('Evidence retention',['Current workspace policy','Review available durations']))}${setting('Private monthly outcomes','Optional summaries derived from retained verified evidence.',toggle('Private monthly outcomes',false))}<div class="savebar"><span>Example controls · effective retention is server-defined.</span>${btn('Review sample changes','retention-save',true)}</div></section><aside class="side-note"><h3>Expired is not verified</h3><p>Deleted or expired records cannot continue to establish a current verified result.</p><p>Review your exports and any supported hold requirements before changing retention.</p></aside></div>`;}
function audit(){return head('Who changed what.','Administrative changes, separate from scan activity.',btn('Export sample log','export',false,'Download'))+`<div class="toolbar">${pick('Audit event',['All changes','Policy changes','Membership changes'])}${pick('Audit date',['Last 7 days','Last 30 days'])}</div>`+table(['Time','Actor','Action','Scope'],[['Today, 09:34','Studio admin','Updated scan rules',workspaceName],['15 Sep, 14:20','Studio owner','Invited Alex Morgan',workspaceName],['14 Sep, 11:08','Studio owner','Connected GitHub installation','studio']])+`<p class="micro">Illustrative administrative events only. <a class="link" href="#timeline">Open release timeline ${icon('ArrowRight')}</a></p>`;}
function health(){return head('Connection health.','Repair a specific connection without guessing from a score.')+table(['Connection','Access','Last event','Action'],[[entity('GitHub · studio','Repository access','Github','sources'),status('Available','passed'),'Today, 10:41',b('View repositories','sources/github')],[entity('app.example.com','Website ownership','Globe','scan/website'),status('Verification required','warn'),'No observation',b('Verify ownership','scan/website')]])+section('What these states mean',`<div class="two-col"><div><h3>Connected</h3><p class="micro">Access is configured. This does not mean a release has been inspected.</p></div><div><h3>Checked</h3><p class="micro">A recorded check exists. Open its result to see scope, findings and limitations.</p></div></div>`);}
function tokens(){return head('Connect your build pipeline.','Create credentials with a clear purpose, scope and expiry.',btn('Create token','token',true,'Plus'))+table(['Token','Scope','Expiry',''],[[entity('CI artifact uploads','Last used today, 10:41','KeyRound','tokens'),'Submit artifact scans','30 Sep 2026',btn('Revoke','revoke')]])+section('One purpose per credential',`<div class="split"><div class="quiet-panel"><h3>Submit the packed artifact</h3><p>Your CI workflow sends the exact release bytes for inspection and receives a result.</p><p class="micro">Do not place the token in source control. A newly created token is shown once.</p></div><aside class="side-note"><h3>Separate permissions</h3><p>Scan tokens do not automatically grant release-gate access or agent access.</p></aside></div>`);}
function registries(){return head('Access private packages.','Keep registry credentials scoped and separate from scan evidence.',btn('Add registry','registry',true,'Plus'))+table(['Registry','Credential','Last check',''],[[entity('registry.example.com','Private package registry','LockKeyhole','registries'),status('Configured','neutral'),status('Not tested','warn'),btn('Review configuration','registry')]])+`<p class="micro">A saved credential does not establish that a package can be downloaded or that it has passed a scan.</p>`;}
const briefs={welcome:'First-time users get one clear route to useful evidence.',overview:'Returning users see the latest decision and recent evidence.',scan:'One source form at a time. Basic actions remain visible.',progress:'Show queued versus inspecting versus completed honestly.',result:'Result, affected file, explanation and next action in one place.',rebuild:'Separate investigation, human review and a new artifact check.',verified:'Show the before/after evidence without rewriting the original.',releases:'Find saved evidence; attempts are a separate tab.',sources:'Separate connection state from check outcome.',alerts:'A concise inbox for response, not a second evidence dashboard.',timeline:'A factual, dated sequence linked back to evidence.',notifications:'Configured, tested and delivered are distinct states.',policy:'Visible rule groups with an explicit save boundary.',team:'Named invitations and clear workspace roles.',workspaces:'Switch workspaces without mixing their evidence or access.',billing:'Coverage, end date, price and provider availability upfront.',retention:'Explain the effect of expiry before changing it.',audit:'Administrative history stays separate from release activity.',health:'Specific repair actions, no decorative health score.',tokens:'Purpose, scope and expiry before issuing credentials.',registries:'Configured credentials are not a successful package check.'};
function journey(){return head('One app. One clear release journey.','A connected design study—not a claim that every integration is live.',b('Start the walkthrough','welcome',true))+`<div class="journey-line">${[['01','Choose','welcome','Connect or upload'],['02','Inspect','scan','Submit the exact bytes'],['03','Understand','result','Review a scoped result'],['04','Correct','rebuild','Record and check a fix'],['05','Keep','releases','Return to saved proof'],['06','Follow up','notifications','Monitor recorded outcomes']].map(([n,t,r,d])=>`<a class="journey-stop" href="#${r}"><b>${n}</b><strong>${t}</strong><p>${d}</p></a>`).join('')}</div>${notice('Design contract','One shared shell, readable type, quiet surfaces, restrained corners, visible task tabs and short contextual help. No hidden primary workflow steps.')}<div class="section-head"><h2>Every screen, with a purpose</h2><a class="link" href="#concepts">View visual concepts ${icon('ArrowUpRight')}</a></div><div class="route-grid">${Object.entries(briefs).map(([r,copy],i)=>`<a class="route-card" href="#${r}"><small>${String(i+1).padStart(2,'0')} / ${r==='billing'?'ORGANISATION':'WORKSPACE'}</small><h3>${icon(routeIcons[r])} ${routeNames[r]}</h3><p>${copy}</p></a>`).join('')}</div><div class="section"><h2>Review the awkward states too.</h2><p class="micro">Use Preview state above any screen to inspect a new workspace, load failure, read-only access or ended coverage. No fake success while data is unavailable.</p></div>`;}
function concepts(){return head('One visual language.','Three anchor screens, followed through into the clickable pages.',b('Explore the screens','journey'))+`<div class="concepts">${[['Overview','overview'],['Scan entry','scan'],['Finding and next action','finding']].map(([title,file])=>`<section><div class="section-head"><h2>${title}</h2></div><img src="assets/${file}-concept.png" alt="${title} generated design concept"></section>`).join('')}</div>`;}
function render(){[route,sub]=location.hash.slice(1).split('/');route=routeNames[route]?route:'overview';sub=sub||'';document.body.classList.remove('menu-open');drawShell();const screens={journey,welcome,overview,scan,progress,result,rebuild,verified:()=>result(true),releases,sources,alerts,timeline,notifications,policy,team,workspaces,billing,retention,audit,health,tokens,registries,concepts};let content=mode==='error'?head(routeNames[route],'The current data could not be loaded.')+empty('We couldn’t load this screen.','Previous records and editing controls are withheld until the current workspace can be confirmed.',btn('Retry preview','retry',true,'RefreshCw'),'CircleAlert'):screens[route]();if(mode==='empty'&&!['journey','concepts','welcome','overview','scan','releases','sources','alerts'].includes(route))content=head(routeNames[route],'This workspace has no records for this task yet.')+empty('Nothing here yet','Start with a scan, then return to configure this part of your workspace.',b('Run your first scan','scan',true),routeIcons[route]);if(mode==='readonly')content=notice('Viewer access','You can review saved evidence. Changes require a workspace administrator.')+content;if(mode==='ended')content=notice('Coverage has ended','New scans and monitoring are paused. Your saved evidence remains available.')+content;$('#main').innerHTML=(['journey','concepts'].includes(route)?'':statePicker())+content;if(mode==='readonly')$('#main').querySelectorAll('input,textarea,select,[data-action]').forEach(el=>{if(el.id!=='state'&&!['retry','search','finding-focus','export','proof'].includes(el.dataset.action))el.disabled=true;});if(mode==='ended')$('#main').querySelectorAll('[data-action=scan],[data-action=rebuild]').forEach(el=>el.disabled=true);document.title=`${routeNames[route]} · NoSpoilers design study`;window.scrollTo(0,0);}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
let returnFocus;function modal(title,body){returnFocus=document.activeElement;$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="Close dialog">${icon('X')}</button></div>${body}`;$('#dialog').showModal();$('#dialog').querySelector('input,button')?.focus()}
function close(){ $('#dialog').close();returnFocus?.focus() }
const sampleSave=label=>{close();toast(`${label} saved in this preview only. No live change.`)};
function search(){modal('Find a screen or release',`<label class="field">Search<input id="search-input" type="search" placeholder="Releases, policy, web build…" autofocus></label><div id="search-results">${searchResults('')}</div>`);$('#search-input').focus()}
function searchResults(q){return Object.entries(routeNames).filter(([r,t])=>(t+' '+(briefs[r]||'')).toLowerCase().includes(q.toLowerCase())).map(([r,t])=>`<a class="search-result" href="#${r}" data-close="true">${icon(routeIcons[r])}${t}<small>Screen</small></a>`).join('')||'<p class="micro">No matching screen. Try “release” or “policy”.</p>'}
function act(action){switch(action){case'close':close();break;case'collapse':document.body.classList.toggle('collapsed');document.body.classList.remove('menu-open');break;case'menu':document.body.classList.toggle('menu-open');break;case'search':search();break;case'workspace':modal('Workspaces',`<a class="search-result" href="#overview" data-close="true"><span class="avatar">ST</span>${esc(workspaceName)}<small>Current</small></a><button class="search-result" data-action="create-workspace">${icon('Plus')}Create workspace</button>`);break;case'create-workspace':close();modal('Create a workspace',`${field('Workspace name','<input id="workspace-name" placeholder="Workspace name">')}${btn('Create sample workspace','workspace-save',true)}`);break;case'workspace-save':{const name=$('#workspace-name').value.trim();if(!name)return $('#workspace-name').focus();workspaceName=name;close();mode='empty';location.hash='overview';render();break;}case'sample-file':sampleFile=true;render();toast('Sample archive selected. No local file is read.');break;case'remove-file':sampleFile=false;render();break;case'scan':scanOrigin=sub==='github'?'github':'upload';location.hash='progress';break;case'older-evidence':modal('Web build · v1.7.9',`<p>web-build.zip ·52 files ·11 Sep2026 ·policy passed in this illustrative history.</p><p class="micro">This is separate from the current v1.8.0 finding and its rebuilt artifact.</p>${btn('Back to releases','close',true)}`);break;case'api-evidence':modal('API package · v2.4.1',`${notice('Policy passed','api-package.tgz ·218 files ·14 Sep2026 ·production not checked','passed')}${btn('Back to releases','close',true)}`);break;case'finding-focus':$('#finding-title').focus();break;case'connect':modal('Connect a source',`<p>Choose a source for this sample workspace.</p><div class="section">${b('GitHub release','scan/github',false,'Github')}${b('Production website','scan/website',false,'Globe')}</div><p class="micro">No GitHub permissions are requested in this prototype.</p>`);break;case'ownership':modal('Verify domain ownership',`${field('Verification method',pick('Verification method',['HTTPS file','DNS TXT']))}<div class="path"><code>nospoilers-verification=sample-only</code></div><p class="micro">Add the value to the domain you control. This preview does not perform a network check.</p>${btn('Close preview','close')}`);break;case'proof':modal('Proof verification',`${notice('Sample signature valid','This illustrates verification of an unchanged receipt, not a fresh scan.','passed')}<p class="micro">Artifact: web-build-v1.8.0.zip · production not checked.</p>${btn('Done','close',true)}`);break;case'review-save':if(!$('#review-check').checked)return toast('Review confirmation is required.');if(!/^[a-f0-9]{40}$/i.test($('#commit').value))return toast('Enter the full 40-character commit hash.');if(!$('#review-note').value.trim())return toast('Add an investigation note.');reviewed=true;$('#rebuild-button').disabled=false;toast('Sample review recorded. You can now check the rebuild.');break;case'rebuild':rebuilt=true;location.hash='verified';break;case'alert-finding':$('#alert-body').innerHTML=alertDetail(false);break;case'alert-incomplete':$('#alert-body').innerHTML=alertDetail(true);break;case'acknowledge':alertState='progress';location.hash='alerts/progress';toast('Sample response moved to In progress. Evidence is unchanged.');break;case'assign':modal('Assign alert',`${field('Assignee',pick('Assignee',['Studio admin','Alex Morgan']))}${btn('Save assignment','save',true)}`);break;case'destination':modal('Add notification destination',`${field('Type',pick('Destination type',['Webhook']))}${field('Name','<input placeholder="Release notifications">')}${field('Endpoint','<input type="url" placeholder="https://hooks.example.com/…">')}<p class="micro">Design form only. Do not enter a private webhook or credential.</p>${btn('Save sample destination','save',true)}`);break;case'notification-test':notificationSent=true;render();toast('Simulated delivery recorded. No external message sent.');break;case'policy-save':savedPolicy=true;render();toast('Sample rules saved. Live policy is unchanged.');break;case'exception':modal('Propose an exception',`${field('Rule',pick('Rule',['Embedded source map']))}${field('Reason','<textarea placeholder="Why should this scoped finding be excepted?"></textarea>')}${field('Expires','<input type="date" value="2026-09-23">')}${btn('Save sample proposal','save',true)}`);break;case'invite':modal('Invite a person',`${field('Email address','<input type="email" placeholder="name@example.com">')}${field('Role',pick('Role',['Viewer','Member','Admin']))}<p class="micro">This workspace only. No actual invitation will be sent.</p>${btn('Preview invitation','save',true)}`);break;case'role':modal('Edit workspace role',`${field('Alex Morgan',pick('Workspace role',['Viewer','Member','Admin']))}${btn('Save sample role','save',true)}`);break;case'token':modal('Create a scan token',`${field('Purpose','<input placeholder="CI uploads">')}${field('Expiry','<input type="date" value="2026-09-30">')}<p class="micro">Sample permission: submit artifact scans. No real credential is created.</p>${btn('Preview token','token-preview',true)}`);break;case'token-preview':$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>Copy once</h2><button data-action="close">${icon('X')}</button></div><div class="path"><code>ns_preview_NOT_A_REAL_TOKEN</code></div><p class="micro">This is a design placeholder, never a usable secret.</p>${btn('Done','close',true)}`;break;case'revoke':modal('Revoke CI artifact uploads?',`<p>The real action would prevent future use of this credential.</p><div class="section actions">${btn('Cancel','close')}${btn('Simulate revoke','save',true)}</div>`);break;case'registry':modal('Registry connection',`${field('Registry host','<input value="registry.example.com">')}${field('Credential','<input type="password" placeholder="Use a placeholder only">')}<p class="micro">No credentials are saved or transmitted.</p>${btn('Save sample configuration','save',true)}`);break;case'retention-save':modal('Review retention change',`<p>Check how the selected policy affects available evidence before saving.</p><p class="micro">No live retention or deletion is performed.</p><div class="section">${btn('Confirm sample change','save',true)}</div>`);break;case'export':{const blob=new Blob(['time,actor,action\n2026-09-16,Sample admin,Sample policy change\n'],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nospoilers-design-sample-audit.csv';a.click();URL.revokeObjectURL(a.href);break;}case'retry':mode='normal';render();break;case'save':sampleSave('Sample changes');break;}}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){e.preventDefault();act(action.dataset.action)}const a=e.target.closest('a[href^="#"]');if(a&&$('#dialog').open)close()});document.addEventListener('change',e=>{if(e.target.id==='state'){mode=e.target.value;render()}if(e.target.getAttribute('aria-label')==='Result filter')document.querySelectorAll('#release-table tbody tr').forEach(tr=>tr.hidden=e.target.value!=='All results'&&!tr.textContent.includes(e.target.value))});document.addEventListener('input',e=>{if(e.target.id==='search-input')$('#search-results').innerHTML=searchResults(e.target.value);if(e.target.id==='release-search')document.querySelectorAll('#release-table tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(e.target.value.toLowerCase()))});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#dialog').open)search()}});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))close()});window.addEventListener('hashchange',render);render();
